reducedMotion:
@media (prefers-reduced-motion: reduce) {
  .hero-title { animation: auto ease 0s 1 normal none running none; transition: color 0.25s ease-out, text-shadow 0.25s ease-out; }
  .hero-title-char { animation: auto ease 0s 1 normal none running none; opacity: 1; transform: none; }
  .hero-title-hot { text-shadow: rgba(255, 90, 31, 0.5) 0px 0px 8px; }
}
